def transpose(matrix):
    if not matrix:
        return []
    return [list(row) for row in zip(*matrix)]


def frequencies(items):
    counts = {}
    for item in items:
        counts[item] = counts.get(item, 0) + 1
    return dict(sorted(counts.items(), key=lambda x: x[1], reverse=True))


def partition(predicate, items):
    truthy = []
    falsy = []
    for item in items:
        if predicate(item):
            truthy.append(item)
        else:
            falsy.append(item)
    return (truthy, falsy)
